fn resolve<'a>(_parts: &'a mut Parts, name: &'a &'static str) -> ResolveFuture<'a> {
    Box::pin(async move {
        Ok(Some(
            Principal::from_verified("urn:test:accounts", "subject", name, None).unwrap(),
        ))
    })
