    let result = App::<()>::new().try_configure(|_| Err::<App, _>(BadConfiguration));
    assert!(matches!(result, Err(BadConfiguration)));
    let configured =
        App::<()>::new().try_configure(|app| Ok::<_, BadConfiguration>(app.get("/", selected)));
    assert!(configured.is_ok());
